    const combinations = result.matrix.include || [];

    expect(combinations.length).toBe(4);
    expect(combinations).toContainEqual({
      os: "ubuntu-latest",
      nodeVersion: "16",
    });
    expect(combinations).toContainEqual({
      os: "ubuntu-latest",
      nodeVersion: "18",
    });
    expect(combinations).toContainEqual({
      os: "windows-latest",
      nodeVersion: "16",
    });
    expect(combinations).toContainEqual({
      os: "windows-latest",
      nodeVersion: "18",
    });
  });

